class AssessmentSystem:
    def __init__(self):
        self.students = {}

    def add_student(self, name, grade, major):
        if name not in self.students:
            self.students[name] = {'name': name, 'grade': grade, 'major': major, 'courses': {}}

    def add_course_score(self, name, course, score):
        if name in self.students:
            if course in self.students[name]['courses']:
                self.students[name]['courses'][course] = max(self.students[name]['courses'][course], score)
            else:
                self.students[name]['courses'][course] = score

    def get_gpa(self, name):
        if name in self.students:
            grades = [score for course, score in self.students[name]['courses'].items() if score is not None]
            if grades:
                return sum(grades) / len(grades)
            else:
                return None
        return None

    def get_all_students_with_fail_course(self):
        return [name for name, student in self.students.items() if any(score is None for score in student['courses'].values())]

    def get_course_average(self, course):
        if course in self.students:
            scores = [score for name, student in self.students.items() if course in student['courses']]
            if scores:
                return sum(scores) / len(scores)
            else:
                return None
        return None

    def get_top_student(self):
        if not self.students:
            return None
        top_student = max(self.students, key=lambda x: self.get_gpa(x))
        return top_student
