class DecryptionUtils:
    def __init__(self, key):
        self.key = key

    def caesar_decipher(self, ciphertext, shift):
        plaintext = ""
        for i in range(len(ciphertext)):
            if ciphertext[i].isalpha():
                shift_amount = shift % 26
                if ciphertext[i].isupper():
                    plaintext += chr((ord(ciphertext[i]) - 65 - shift_amount) % 26 + 65)
                else:
                    plaintext += chr((ord(ciphertext[i]) - 97 - shift_amount) % 26 + 97)
            else:
                plaintext += ciphertext[i]
        return plaintext

    def vigenere_decipher(self, ciphertext):
        plaintext = ""
        key_index = 0
        for i in range(len(ciphertext)):
            if ciphertext[i].isalpha():
                shift_amount = (ord(self.key[key_index % len(self.key)]) - 65)
                if ciphertext[i].isupper():
                    plaintext += chr((ord(ciphertext[i]) - 65 - shift_amount) % 26 + 65)
                else:
                    plaintext += chr((ord(ciphertext[i]) - 97 - shift_amount) % 26 + 97)
                key_index += 1
            else:
                plaintext += ciphertext[i]
        return plaintext

    def rail_fence_decipher(self, encrypted_text, rails):
        plaintext = ""
        rail_index = 0
        down = True
        for i in range(len(encrypted_text)):
            plaintext += encrypted_text[i]
            if rail_index == rails - 1 and down:
                down = False
            elif rail_index == 0 and not down:
                down = True
            if down:
                rail_index += 1
            else:
                rail_index -= 1
        return plaintext
