class DiscountStrategy:
    def __init__(self, customer, cart, promotion=None):
        self.customer = customer
        self.cart = cart
        self.promotion = promotion
        self.total()

    def total(self):
        self.total_cost = sum(item['price'] * item['quantity'] for item in self.cart)
        return self.total_cost

    def due(self):
        if self.promotion:
            self.discount = self.promotion(self)
        else:
            self.discount = 0
        return self.total_cost - self.discount

    @staticmethod
    def FidelityPromo(order):
        fidelity_points = order.customer['fidelity']
        return fidelity_points * 0.05 if fidelity_points >= 1000 else 0

    @staticmethod
    def BulkItemPromo(order):
        item_quantities = {item['product']: item['quantity'] for item in order.cart}
        discount = sum(item['price'] * item['quantity'] * 0.1 if item['quantity'] >= 20 else 0 for item in order.cart)
        return discount

    @staticmethod
    def LargeOrderPromo(order):
        unique_products = len({item['product'] for item in order.cart})
