class EightPuzzle:
    def __init__(self, initial_state):
        self.initial_state = initial_state
        self.goal_state = [[1, 2, 3], [4, 5, 6], [7, 8, 0]]
        self.open_list = [self.initial_state]
        self.visited = set([self.initial_state])

    def find_blank(self, state):
        for i in range(len(state)):
            for j in range(len(state[i])):
                if state[i][j] == 0:
                    return i, j
        return None, None

    def move(self, state, direction):
        i, j = self.find_blank(state)
        if direction == 'up' and i > 0:
            new_state = [row[:] for row in state]
            new_state[i][j], new_state[i-1][j] = new_state[i-1][j], new_state[i][j]
            return new_state
        elif direction == 'down' and i < 2:
            new_state = [row[:] for row in state]
            new_state[i][j], new_state[i+1][j] = new_state[i+1][j], new_state[i][j]
            return new_state
        elif direction == 'left' and j > 0:
            new_state = [row[:] for row in state]
            new_state[i][j], new_state[i][j-1] = new_state[i][j-1], new_state[i][j]
            return new_state
        elif direction == 'right' and j < 2:
            new_state = [row[:] for row in state]
            new_state[i][j], new_state[i][j+1] = new_state[i][j+1], new_state[i][j]
            return new_state
        return state

    def get_possible_moves(self, state):
        possible_moves = []
        i, j = self.find_blank(state)
        if i > 0:
            possible_moves.append('up')
        if i < 2:
            possible_moves.append('down')
        if j > 0:
            possible_moves.append('left')
        if j < 2:
            possible_moves.append('right')
        return possible_moves

    def solve(self):
        while self.open_list:
            current_state = self.open_list.pop(0)
            if current_state == self.goal_state:
                return []
            for direction in self.get_possible_moves(current_state):
                new_state = self.move(current_state, direction)
                if new_state not in self.visited:
                    self.open_list.append(new_state)
                    self.visited.add(new_state)
        return []
