class EightPuzzle:
    def __init__(self, initial_state):
        self.initial_state = initial_state
        self.goal_state = [[1, 2, 3], [4, 5, 6], [7, 8, 0]]

    def find_blank(self, state):
        blank_idx = state.index(0)
        row = blank_idx // 3
        col = blank_idx % 3
        return row, col

    def move(self, state, direction):
        row, col = self.find_blank(state)
        if direction == 'up' and row > 0:
            new_state = [row[:] for row in state]
            new_state[row][col], new_state[row - 1][col] = new_state[row - 1][col], new_state[row][col]
            return new_state
        elif direction == 'down' and row < 2:
            new_state = [row[:] for row in state]
            new_state[row][col], new_state[row + 1][col] = new_state[row + 1][col], new_state[row][col]
            return new_state
        elif direction == 'left' and col > 0:
            new_state = [row[:] for row in state]
            new_state[row][col], new_state[row][col - 1] = new_state[row][col - 1], new_state[row][col]
            return new_state
        elif direction == 'right' and col < 2:
            new_state = [row[:] for row in state]
            new_state[row][col], new_state[row][col + 1] = new_state[row][col + 1], new_state[row][col]
            return new_state
        return state

    def get_possible_moves(self, state):
        blank_idx = state.index(0)
        row, col = self.find_blank(state)
        possible_moves = []
        if row > 0:
            possible_moves.append('up')
        if row < 2:
            possible_moves.append('down')
        if col > 0:
            possible_moves.append('left')
        if col < 2:
            possible_moves.append('right')
        return possible_moves

    def solve(self):
        open_list = [self.initial_state]
        closed_list = []
        path = []
        while open_list:
            current_state = open_list.pop(0)
            if current_state == self.goal_state:
                return path
            closed_list.append(current_state)
            for direction in self.get_possible_moves(current_state):
                new_state = self.move(current_state, direction)
                if new_state not in closed_list and new_state not in open_list:
                    open_list.append(new_state)
                    path.append(direction)
        return None
