class EncryptionUtils:
    def __init__(self, key):
        self.key = key

    def caesar_cipher(self, plaintext, shift):
        result = ""
        for char in plaintext:
            if char.isalpha():
                offset = ord('a') if char.islower() else ord('A')
                shift = shift % 26
                result += chr((ord(char) - offset + shift) % 26 + offset)
            else:
                result += char
        return result

    def vigenere_cipher(self, plaintext):
        result = ""
        key_index = 0
        for char in plaintext:
            if char.isalpha():
                offset = ord('a') if char.islower() else ord('A')
                shift = ord(self.key[key_index % len(self.key)]) - ord('a')
                shift = shift % 26
                result += chr((ord(char) - offset + shift) % 26 + offset)
                key_index += 1
            else:
                result += char
        return result

    def rail_fence_cipher(self, plaintext, rails):
        result = [""] * rails
        direction = 1
        row = 0
        for char in plaintext:
            result[row] += char
            if direction == 1:
                row += 1
            else:
                row -= 1
            if row == 0 or row == rails - 1:
                direction = -direction
        return "".join(result)
