class IPAddress:
    def __init__(self, ip_address):
        self.ip_address = ip_address

    def is_valid(self):
        try:
            # Split the IP address by '.' and convert each part to an integer
            parts = [int(part) for part in self.ip_address.split('.')]
            # Check if each part is in the range 0-255
            return all(0 <= part <= 255 for part in parts)
        except ValueError:
            # If any part cannot be converted to an integer or is out of range, the IP address is invalid
            return False

    def get_octets(self):
        # If the IP address is valid, split it into four octets and return them as a list
        if self.is_valid():
            return self.ip_address.split('.')
        return []

    def get_binary(self):
        # If the IP address is valid, convert each octet to binary and concatenate them with '.' as separators
        if self.is_valid():
            return '.'.join(format(part, '08b') for part in self.ip_address.split('.'))
        return ''
