class Manacher:
    def __init__(self, input_string) -> None:
        self.input_string = input_string

    def palindromic_length(self, center, diff, string):
        if diff < 0 or center + diff < len(string) and string[center - diff] == string[center + diff]:
            diff += 1
            return self.palindromic_length(center, diff, string)
        else:
            return diff - 1

    def palindromic_string(self):
        n = len(self.input_string)
        palindrome_length = [0] * n
        center = 0
        max_length = 0
        start = 0

        for i in range(n):
            reflection = center - i
            palindrome_length[i] = max(0, min(palindrome_length[reflection], center + max_length - i))

            while i - palindrome_length[i] >= 0 and i + palindrome_length[i] < n and self.input_string[i - palindrome_length[i]] == self.input_string[i + palindrome_length[i]]:
                palindrome_length[i] += 1

            if palindrome_length[i] > max_length:
                max_length = palindrome_length[i]
                center = i

        start = center - max_length // 2
        return self.input_string[start:start + max_length]
