class PushBoxGame:
    def __init__(self, map):
        self.map = map
        self.player_row = 0
        self.player_col = 0
        self.targets = []
        self.boxes = []
        self.target_count = 0
        self.is_game_over = False
        self.init_game()

    def init_game(self):
        self.player_row = 0
        self.player_col = 0
        self.target_count = 0
        self.is_game_over = False

        for row_idx, row in enumerate(self.map):
            for col_idx, cell in enumerate(row):
                if cell == 'O':
                    self.player_row, self.player_col = row_idx, col_idx
                elif cell == 'G':
                    self.targets.append((row_idx, col_idx))
                    self.target_count += 1
                elif cell == 'X':
                    self.boxes.append((row_idx, col_idx))

    def check_win(self):
        return len(self.boxes) == self.target_count

    def move(self, direction):
        if direction not in ['w', 's', 'a', 'd']:
            return False

        new_row, new_col = self.player_row, self.player_col

        if direction == 'w':
            new_row -= 1
        elif direction == 's':
            new_row += 1
        elif direction == 'a':
            new_col -= 1
        elif direction == 'd':
            new_col += 1

        if 0 <= new_row < len(self.map) and 0 <= new_col < len(self.map[0]):
            if self.map[new_row][new_col] not in ['#', 'X', '@']:
                if direction == 'w' and new_col == self.player_col:
                    if new_row == self.boxes[0][0]:
                        self.map[new_row][new_col] = 'X'
                        self.boxes[0] = (new_row, new_col)
                        return True
                elif direction == 's' and new_col == self.player_col:
                    if new_row == self.boxes[0][0]:
                        self.map[new_row][new_col] = 'X'
                        self.boxes[0] = (new_row, new_col)
                        return True
                elif direction == 'a' and new_row == self.player_row:
                    if new_col == self.boxes[0][1]:
                        self.map[new_row][new_col] = 'X'
                        self.boxes[0] = (new_row, new_col)
                        return True
                elif direction == 'd' and new_row == self.player_row:
                    if new_col == self.boxes[0][1]:
                        self.map[new_row][new_col] = 'X'
                        self.boxes[0] = (new_row, new_col)
                        return True
                else:
                    self.map[self.player_row][self.player_col] = ' '
                    self.player_row, self.player_col = new_row, new_col
                    if self.check_win():
                        self.is_game_over = True
                        return True
                    self.map[new_row][new_col] = '@'
                    return True
        return False

    def print_map(self):
        for row in self.map:
            print(row)
        print(f"Player: ({self.player_row}, {self.player_col})")
        print(f"Boxes: {self.boxes}")
        print(f"Targets: {self.targets}")
        print(f"Game Over: {self.is_game_over}")
