class PushBoxGame:
    def __init__(self, map):
        self.map = map
        self.player_row = 0
        self.player_col = 0
        self.targets = []
        self.boxes = []
        self.target_count = 0
        self.is_game_over = False
        self.init_game()

    def init_game(self):
        for row in range(len(self.map)):
            for col in range(len(self.map[row])):
                if self.map[row][col] == 'O':
                    self.player_row = row
                    self.player_col = col
                elif self.map[row][col] == 'G':
                    self.targets.append((row, col))
                    self.target_count += 1
                elif self.map[row][col] == 'X':
                    self.boxes.append((row, col))

    def check_win(self):
        return self.boxes == self.targets

    def move(self, direction):
        new_row, new_col = self.player_row, self.player_col
        if direction == 'w':
            new_row -= 1
        elif direction == 's':
            new_row += 1
        elif direction == 'a':
            new_col -= 1
        elif direction == 'd':
            new_col += 1

        if self.map[new_row][new_col] != '#' and (new_row, new_col) not in self.boxes:
            self.player_row, self.player_col = new_row, new_col
            if self.map[new_row][new_col] == 'G':
                self.boxes.append((new_row, new_col))
                self.targets.remove((new_row, new_col))
                self.target_count -= 1
                if self.check_win():
                    self.is_game_over = True
            else:
                self.boxes.remove((self.player_row, self.player_col))
                self.boxes.append((new_row, new_col))
        elif self.map[new_row][new_col] == 'X':
            self.boxes.remove((self.player_row, self.player_col))
            self.boxes.append((new_row, new_col))
        else:
            return False

        return self.is_game_over
