class SQLQueryBuilder:
    @staticmethod
    def select(table, columns='*', where=None):
        if where is None:
            return f"SELECT {', '.join(columns)} FROM {table}"
        else:
            return f"SELECT {', '.join(columns)} FROM {table} WHERE {' AND '.join(f'{key}={value}' for key, value in where.items())}"

    @staticmethod
    def insert(table, data):
        keys = ', '.join(data.keys())
        values = ', '.join([f"'{value}'" if isinstance(value, str) else str(value) for value in data.values()])
        return f"INSERT INTO {table} ({keys}) VALUES ({values})"

    @staticmethod
    def delete(table, where=None):
        if where is None:
            return f"DELETE FROM {table}"
        else:
            return f"DELETE FROM {table} WHERE {' AND '.join(f'{key}={value}' for key, value in where.items())}"

    @staticmethod
    def update(table, data, where=None):
        keys = ', '.join([f"{key}='{value}'" if isinstance(value, str) else str(value) for key, value in data.items()])
        return f"UPDATE {table} SET {keys} WHERE {' AND '.join(f'{key}={value}' for key, value in where.items())}"
