    def __init__(self, cash_balance):
        self.portfolio = []
        self.cash_balance = cash_balance

    def add_stock(self, stock):
        if stock["quantity"] <= 0:
            raise ValueError("Quantity must be positive")
        self.portfolio.append(stock)
        return True

    def remove_stock(self, stock):
        if stock not in self.portfolio:
            return False
        self.portfolio.remove(stock)
        return True

    def buy_stock(self, stock):
        if stock["quantity"] <= 0:
            raise ValueError("Quantity must be positive")
        price = stock["price"]
        quantity = stock["quantity"]
        new_cash_balance = self.cash_balance - price * quantity
        if new_cash_balance < 0:
            return False
        self.cash_balance = new_cash_balance
        self.add_stock(stock)
        return True

    def sell_stock(self, stock):
        if stock not in self.portfolio:
            return False
        price = stock["price"]
        quantity = stock["quantity"]
        new_cash_balance = self.cash_balance + price * quantity
        if new_cash_balance < 0:
            return False
        self.cash_balance = new_cash_balance
        self.remove_stock(stock)
        return True

    def calculate_portfolio_value(self):
        return sum(stock["price"] * stock["quantity"] for stock in self.portfolio) + self.cash_balance

    def get_portfolio_summary(self):
        total_value = self.calculate_portfolio_value()
        stock_values = [{"name": stock["name"], "value": stock["price"] * stock["quantity"]} for stock in self.portfolio]
        return total_value, stock_values

    def get_stock_value(self, stock):
        return stock["price"] * stock["quantity"]
